selector_to_html = {"a[href=\"#step-1-configure-yaml-files\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Step 1: Configure YAML files<a class=\"headerlink\" href=\"#step-1-configure-yaml-files\" title=\"Link to this heading\">#</a></h2><p>FlagScale uses <a class=\"reference external\" href=\"https://hydra.cc/\">Hydra</a> for configuration management. Every task is driven by two YAML files that work together: an experiment-level file and a task-level file, both in the <code class=\"docutils literal notranslate\"><span class=\"pre\">examples/</span></code> directory. Before running the task, you need to configure these files first.</p>", "a[href=\"multi-platform-training.html#run-the-training-test\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">5. Run the training test<a class=\"headerlink\" href=\"#run-the-training-test\" title=\"Link to this heading\">#</a></h2><p>Monitor device utilization in a second shell:</p>", "a[href=\"#step-2-run-tasks\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Step 2\uff1a Run tasks<a class=\"headerlink\" href=\"#step-2-run-tasks\" title=\"Link to this heading\">#</a></h2><p>FlagScale provides a unified runner for various tasks, including training, inference, reinforcement learning, and serving. Simply specify the configuration file to run the task with a single <code class=\"docutils literal notranslate\"><span class=\"pre\">flagscale</span></code> command. The runner will automatically load the configurations and execute the task. The following sections demonstrate how to run a distributed training task.</p>", "a[href=\"multi-platform-training.html#known-issues-and-workarounds\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">7. Known issues and workarounds<a class=\"headerlink\" href=\"#known-issues-and-workarounds\" title=\"Link to this heading\">#</a></h2><h3>7.1 MetaX<a class=\"headerlink\" href=\"#metax\" title=\"Link to this heading\">#</a></h3><p><strong><code class=\"docutils literal notranslate\"><span class=\"pre\">ImportError:</span> <span class=\"pre\">cannot</span> <span class=\"pre\">import</span> <span class=\"pre\">name</span> <span class=\"pre\">'AttrsDescriptor'</span> <span class=\"pre\">from</span> <span class=\"pre\">'triton.compiler.compiler'</span></code></strong> \u2014 after switching to FlagTree, PyTorch\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">torch._inductor</span></code> cannot find <code class=\"docutils literal notranslate\"><span class=\"pre\">AttrsDescriptor</span></code>. Add a shim to <code class=\"docutils literal notranslate\"><span class=\"pre\">/opt/conda/lib/python3.12/site-packages/triton/compiler/compiler.py</span></code>:</p>", "a[href=\"#experiment-level-yaml\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Experiment-level YAML<a class=\"headerlink\" href=\"#experiment-level-yaml\" title=\"Link to this heading\">#</a></h3><p>Use the <code class=\"docutils literal notranslate\"><span class=\"pre\">examples/qwen3/conf/serve.yaml</span></code> as an example to explain this configuration file.</p><p>The experiment-level file is the entry point for <code class=\"docutils literal notranslate\"><span class=\"pre\">flagscale</span></code> commands. It defines a global context for the run:</p>", "a[href=\"multi-platform-training.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-Platform Training and Testing<a class=\"headerlink\" href=\"#multi-platform-training-and-testing\" title=\"Link to this heading\">#</a></h1><p>FlagScale has no hardware requirements of its own \u2014 it orchestrates training through the FlagOS plugins. This guide shows how to drive an end-to-end training job on four non-NVIDIA platforms (MetaX, Hygon, Ascend, T-Head PPU) with the plugin stack underneath.</p><p>Platform-specific plugin installation is documented in the plugin guides:</p>", "a[href=\"#task-level-yaml\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Task-level YAML<a class=\"headerlink\" href=\"#task-level-yaml\" title=\"Link to this heading\">#</a></h3><p>Use the <code class=\"docutils literal notranslate\"><span class=\"pre\">examples/qwen3/conf/serve/8b.yaml</span></code> as an example to explain this configuration file.</p><p>The task-level YAML file specifies the model, dataset, and parameters for specific tasks such as training or inference. Every parameter in this file maps directly to an argument accepted by the backend engine, with hyphens (-) replaced by underscores (_).</p>", "a[href=\"multi-platform-training.html#platform-environment-variables\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Platform environment variables<a class=\"headerlink\" href=\"#platform-environment-variables\" title=\"Link to this heading\">#</a></h2><p>FlagScale passes device visibility through the experiment-level YAML <code class=\"docutils literal notranslate\"><span class=\"pre\">envs</span></code> block. Each platform uses a different variable name.</p>", "a[href=\"#user-guide\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">User Guide<a class=\"headerlink\" href=\"#user-guide\" title=\"Link to this heading\">#</a></h1><p>This guide covers how to configure FlagScale and run training, inference, serving, and reinforcement learning tasks.</p>", "a[href=\"#train\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Train<a class=\"headerlink\" href=\"#train\" title=\"Link to this heading\">#</a></h3><p>Require Megatron-LM-FL enviroment</p>", "a[href=\"#serve\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Serve<a class=\"headerlink\" href=\"#serve\" title=\"Link to this heading\">#</a></h3>", "a[href=\"multi-platform-training.html#configure-the-training-task\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. Configure the training task<a class=\"headerlink\" href=\"#configure-the-training-task\" title=\"Link to this heading\">#</a></h2><h3>4.1 Experiment-level YAML<a class=\"headerlink\" href=\"#experiment-level-yaml\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">examples/qwen3/conf/train.yaml</span></code> selects the task-level config and defines the runner environment:</p>", "a[href=\"multi-platform-training.html#component-versions-used\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Component versions used<a class=\"headerlink\" href=\"#component-versions-used\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#reinforcement-learning\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Reinforcement Learning<a class=\"headerlink\" href=\"#reinforcement-learning\" title=\"Link to this heading\">#</a></h3><p>Require verl-FL environment</p>", "a[href=\"multi-platform-training.html#install-flagscale\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Install FlagScale<a class=\"headerlink\" href=\"#install-flagscale\" title=\"Link to this heading\">#</a></h2><p>Verify, then install the logging dependencies used by the training runs:</p>", "a[href=\"#inference\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Inference<a class=\"headerlink\" href=\"#inference\" title=\"Link to this heading\">#</a></h3><p>Require vLLM-FL environment</p>", "a[href=\"multi-platform-training.html#notes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">8. Notes<a class=\"headerlink\" href=\"#notes\" title=\"Link to this heading\">#</a></h2>", "a[href=\"multi-platform-training.html#run-on-the-flagos-operator-stack\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">6. Run on the FlagOS operator stack<a class=\"headerlink\" href=\"#run-on-the-flagos-operator-stack\" title=\"Link to this heading\">#</a></h2><p>To run the same job through FlagTree and FlagGems instead of the vendor operator library, use the <code class=\"docutils literal notranslate\"><span class=\"pre\">te_fl</span></code> configuration pair and select the FlagOS tier:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
